使用融合tts 需要设置returnPhtone 为true

/**
 * 设置TTS是否返回音素信息，因为历史遗留音素，会存在下列问题
 * 部分音色会忽略音素设置，设置为true依旧不会返回信息，并抛出错误码72205，
 * 如anonyg hbrinf hyanif lunaif_ctn lzyinf swkm zxcm zzxiangm等
 * 部分音素支持返回音素，
 * 如cyangfp dyb gdfanfp gqlanfp hthy jjingfp jlshim lanyuf lchuam lili1f_yubo lucyfa
 * lzliafp madoufp_wenrou madoufp_yubo xbekef xijunma xjingfp xyb xynmamp ychanmp yhchu
 * zhilingfp zhilingfp_huankuai zsmeif dksjif ybyuaf sqksaf zxiyum aningfp lmyanm
 * wqingf_csn ppangf_csn hchunf_ctn mamif xmguof等
 * 其余的音色不支持音素，不会返回音素信息，但是也不会抛出错误码
 *
 * @param phoneReturn 音素开关;
 */
public void setPhoneReturn(boolean phoneReturn) throws DDSNotInitCompleteException {
    checkInitComplete();
    if (mBc != null) {
        TtsTopicUtil.publishSetPhoneReturn(mBc, phoneReturn);
    } else {
        AILog.e(TAG, "setPhoneReturn failed due to null busclient");
    }

}




